NAVY=HexColor("#17324D"); TEAL=HexColor("#1B7F8C"); GOLD=HexColor("#D9A441"); LIGHT=HexColor("#EFF5F7"); PALE=HexColor("#FFF8E8"); GRAY=HexColor("#5B6770")
s=getSampleStyleSheet()
s.add(ParagraphStyle(name="CoverTitle",parent=s["Title"],fontName="Helvetica-Bold",fontSize=24,leading=28,alignment=TA_CENTER,textColor=NAVY,spaceAfter=14))
s.add(ParagraphStyle(name="CoverSub",parent=s["Normal"],fontSize=11,leading=15,alignment=TA_CENTER,textColor=GRAY,spaceAfter=7))
s.add(ParagraphStyle(name="H1x",parent=s["Heading1"],fontName="Helvetica-Bold",fontSize=17,leading=21,textColor=NAVY,spaceBefore=8,spaceAfter=8,keepWithNext=True))
s.add(ParagraphStyle(name="H2x",parent=s["Heading2"],fontName="Helvetica-Bold",fontSize=12.5,leading=15,textColor=TEAL,spaceBefore=8,spaceAfter=4,keepWithNext=True))
s.add(ParagraphStyle(name="Bodyx",parent=s["BodyText"],fontSize=9.1,leading=12.1,spaceAfter=5))
